From e8b2737f205d4238220dcab973e21b20a0640802 Mon Sep 17 00:00:00 2001
From: Yu Watanabe <watanabe.yu+github@gmail.com>
Date: Thu, 21 Feb 2019 17:29:29 +0900
Subject: [PATCH] udev-rules: do not ignore short lines

Otherwise, a short line continues the previous continuation.

This fixes a bug introduced by f10aa08e3e48de7dcb71be348f021c6b1385304f.

diff --git a/src/udev/udev-rules.c b/src/udev/udev-rules.c
index e34ecc6ee9..178a41906f 100644
--- a/src/udev/udev-rules.c
+++ b/src/udev/udev-rules.c
@@ -1496,8 +1496,6 @@ static int parse_file(UdevRules *rules, const char *filename) {
                         continue;

                 len = strlen(line);
-                if (len < 3)
-                        continue;

                 if (continuation && !ignore_line) {
                         if (strlen(continuation) + len >= UTIL_LINE_SIZE)
@@ -1512,7 +1510,7 @@ static int parse_file(UdevRules *rules, const char *filename) {
                         }
                 }

-                if (line[len - 1] == '\\') {
+                if (len > 0 && line[len - 1] == '\\') {
                         if (ignore_line)
                                 continue;

@@ -1528,7 +1526,7 @@ static int parse_file(UdevRules *rules, const char *filename) {

                 if (ignore_line)
                         log_error("Line too long '%s':%u, ignored", filename, line_nr);
-                else
+                else if (len > 0)
                         add_rule(rules, line, filename, filename_off, line_nr);

                 continuation = mfree(continuation);
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the logic that ignored lines shorter than 3 characters, which led to short lines being treated as continuations of the previous line. This resulted in incorrect parsing behavior, as valid short lines were not processed correctly, potentially leading to unexpected results or errors in the udev rules.

        Commit message:
        udev-rules: do not ignore short lines

Otherwise, a short line continues the previous continuation.

This fixes a bug introduced by f10aa08e3e48de7dcb71be348f021c6b1385304f.  

        Patch:

 static int parse_file(UdevRules *rules, const char *filename) {
         _cleanup_free_ char *continuation = NULL;
         _cleanup_fclose_ FILE *f = NULL;
         bool ignore_line = false;
         size_t first_token, i;
         unsigned filename_off;
         int line_nr = 0, r;

         f = fopen(filename, "re");
         if (!f) {
                 if (errno == ENOENT)
                         return 0;

                 return -errno;
         }

         if (null_or_empty_fd(fileno(f))) {
                 log_debug("Skipping empty file: %s", filename);
                 return 0;
         } else
                 log_debug("Reading rules file: %s", filename);

         first_token = rules->token_cur;
         filename_off = rules_add_string(rules, filename);

         for (;;) {
                 _cleanup_free_ char *buf = NULL;
                 size_t len;
                 char *line;

                 r = read_line(f, UTIL_LINE_SIZE, &buf);
                 if (r < 0)
                         return r;
                 if (r == 0)
                         break;

                 line_nr++;
                 line = buf + strspn(buf, WHITESPACE);

                 if (line[0] == '#')
                         continue;

                 len = strlen(line);
-                if (len < 3)
-                        continue;

                 if (continuation && !ignore_line) {
                         if (strlen(continuation) + len >= UTIL_LINE_SIZE)
                                 ignore_line = true;

                         if (!strextend(&continuation, line, NULL))
                                 return log_oom();

                         if (!ignore_line) {
                                 line = continuation;
                                 len = strlen(line);
                         }
                 }

-                if (line[len - 1] == '\\') {
+                if (len > 0 && line[len - 1] == '\\') {
                         if (ignore_line)
                                 continue;

                         line[len - 1] = '\0';
                         if (!continuation) {
                                 continuation = strdup(line);
                                 if (!continuation)
                                         return log_oom();
                         }

                         continue;
                 }

                 if (ignore_line)
                         log_error("Line too long '%s':%u, ignored", filename, line_nr);
-                else
+                else if (len > 0)
                         add_rule(rules, line, filename, filename_off, line_nr);

                 continuation = mfree(continuation);
                 ignore_line = false;
         }

         /* link GOTOs to LABEL rules in this file to be able to fast-forward */
         for (i = first_token+1; i < rules->token_cur; i++) {
                 if (rules->tokens[i].type == TK_A_GOTO) {
                         char *label = rules_str(rules, rules->tokens[i].key.value_off);
                         size_t j;

                         for (j = i+1; j < rules->token_cur; j++) {
                                 if (rules->tokens[j].type != TK_RULE)
                                         continue;
                                 if (rules->tokens[j].rule.label_off == 0)
                                         continue;
                                 if (!streq(label, rules_str(rules, rules->tokens[j].rule.label_off)))
                                         continue;
                                 rules->tokens[i].key.rule_goto = j;
                                 break;
                         }
                         if (rules->tokens[i].key.rule_goto == 0)
                                 log_error("GOTO '%s' has no matching label in: '%s'", label, filename);
                 }
         }
         return 0;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>
